import torch,json,os
p='model.language_model.'
U=W('lm_head.weight'); norm=W(p+'norm.weight')
labels={'months':'January February March April May June July August September October November December'.split(),'weekdays':'Monday Tuesday Wednesday Thursday Friday Saturday Sunday'.split(),'colors':'red blue green yellow orange purple black white brown pink'.split(),'parity':['even','odd'],'boolean':['True','False'],'comparison':['greater','less','equal'],'fraction':['numerator','denominator'],'case':['uppercase','lowercase'],'polarity':['positive','negative'],'roman':['I','II','III','IV','V','VI','VII','VIII','IX','X']}
vecs=[]
for label,words in labels.items():
 ids=list(set(encode(pre+w)[0] for w in words for pre in ['', ' '] if len(encode(pre+w))==1))
 v=(U[ids]*norm).mean(0);vecs.append(v/v.norm())
V=torch.stack(vecs); ranks={}
for l in [0,8,16,24,32,40,48,56,60,63]:
 D=W(p+f'layers.{l}.mlp.down_proj.weight'); S=(V@D)/D.norm(dim=0).clamp_min(1e-8);ranks[l]=S
 print('layer',l,[(lab,int(S[j].argmax()),round(float(S[j].max()),3)) for j,lab in enumerate(labels)])
torch.save({'V':V,'labels':labels,'ranks':ranks},'/work/weights.pt')

